_FALLBACK = '<path d="M12 9v3.75m9-.75a9 9 0 1 1-18 0 9 9 0 0 1 18 0Zm-9 3.75h.008v.008H12v-.008Z" />'


def render_icon(name: str, css_class: str = "w-5 h-5") -> str:
    """Return inline <svg> HTML for `name` (or a fallback glyph if unknown)."""
    inner = ICONS.get(name, _FALLBACK)
    # css_class is developer-controlled; format_html escapes it defensively.
    return format_html(_SVG_OPEN, cls=css_class, inner=mark_safe(inner))
